select * from series(1, 5);
select value from series(0, 20, 5) order by value;
select value, start, stop from series where start = 3 and stop = 6;
select sum(value) from series(1, 100);
select a.value, b.value from series(1,2) a, series(10,11) b;
select * from series;
explain query plan select * from series(1,5);
create virtual table k1 using kv(alpha, beta 'x y');
insert into k1 values('a', 'one'), ('b', 'two');
insert into k1(rowid, k, v) values(10, 'c', 'three');
select rowid, * from k1;
select * from k1 where rowid = 2;
update k1 set v = 'TWO' where k = 'b';
select rowid, * from k1;
delete from k1 where rowid = 1;
select rowid, * from k1;
begin;
insert into k1 values('d', 'four');
commit;
begin;
insert into k1 values('e', 'five');
rollback;
select k, v from k1 where v match 'o';
insert into k1 values('bad', 'x');
insert or ignore into k1 values('bad', 'x');
alter table k1 rename to k2;
select * from k2;
explain query plan select * from k2 where rowid = 10;
drop table k2;
create virtual table k3 using nosuchmodule;
create virtual table k4 using kv;
select * from k4;
create table plain(x);
insert into plain select value from series(1,3);
select * from plain join series(1,2) on plain.x = series.value;
create virtual table k5 using kv(a);
pragma integrity_check;
pragma quick_check;
pragma integrity_check(k5);
drop table k4;
pragma integrity_check;
